// subject builds a fresh implementation and seeds it, so every check runs
// against state no other check touched.
func (c *mixedConfig) subject(
	tb testing.TB,
	factory func() lifecycleafterclose.Mixed,
	wrap func(tb testing.TB, subject lifecycleafterclose.Mixed) lifecycleafterclose.Mixed,
) lifecycleafterclose.Mixed {
	tb.Helper()
	s := factory()
	if c.seed != nil {
		// Reported rather than ignored. A seed that silently failed would leave
		// every check after it running against an empty subject — passing, and
		// asserting nothing.
		//
		// Which seed ran decides what the message can usefully say. The derived
		// one fails for one of two reasons and both are fixable from here, so it
		// names them. A seed the caller supplied is theirs, and telling them to
		// supply one is advice they already took.
		if err := c.seed(tb.Context(), s); err != nil {
			tb.Fatalf("the seed supplied through MixedSeed failed: %v", err)
		}
	}
	if wrap != nil {
		s = wrap(tb, s)
	}
	return s
}

// dropped reports whether a path was declined through MixedWithout.
//
// Named rather than inlined because the drop set is read from two places: here,
// and by whatever registered through the seam — which reports under paths this
// file has never heard of and must answer the same question about them.
func (c *mixedConfig) declined(path string) bool {
	_, ok := c.without[path]
	return ok
}

// mixedPaths is every path this file reports a check under.
//
// The set a MixedWithout argument has to be a member of. Declared
// rather than observed: a check that did not run is not a check that does not
// exist — an integration-only method skips without ever consulting the drop
// set, and reading that as a phantom would fail a correct suite on a machine
// with the environment unset.
//
//nolint:gochecknoglobals // the emitted check paths, read-only after init.
var mixedPaths = map[string]struct{}{
	"Close/smoke":                       {},
	"Close/reports a cancelled context": {},
	"Close/reports an expired deadline": {},
	"Close/tolerates a nil context":     {},
	"Work/smoke":                        {},
	"Work/reports a cancelled context":  {},
	"Work/reports an expired deadline":  {},
	"Work/tolerates a nil context":      {},
	"Work/lifecycleafterclose":          {},
}

// phantoms names every MixedWithout path that declines nothing.
//
// A drop that drops nothing is this option's silent half: the consumer wrote
// it against a check since renamed, or never emitted for that method at all,
// and every run after reads green while asserting one thing more than its
// author believes. Extensions carry their own names — the seam reports under
// paths this file has never heard of — so they count as known too.
func (c *mixedConfig) phantoms() []string {
	known := func(p string) bool {
		if _, ok := mixedPaths[p]; ok {
			return true
		}
		for _, e := range c.extensions {
			if e.name == p {
				return true
			}
		}
		for _, on := range c.onClose {
			if "Close"+"/"+on.name == p {
				return true
			}
		}
		for _, on := range c.onWork {
			if "Work"+"/"+on.name == p {
				return true
			}
		}
		return false
	}
	var out []string
	for p := range c.without {
		if !known(p) {
			out = append(out, p)
		}
	}
	slices.Sort(out)
	return out
}

// run executes one check unless it was dropped, reporting the drop rather than
// silently omitting it.
func (c *mixedConfig) run(t *testing.T, path, name string, fn func(tb testing.TB)) {
	t.Helper()
	if c.declined(path) {
		t.Run(name, func(t *testing.T) {
			t.Skipf("dropped through MixedWithout(%q)", path)
		})
		return
	}
	t.Run(name, func(t *testing.T) {
		t.Parallel()
		fn(t)
	})
}

